/* Optional icon, Unicode and text-art presentations.
   No shipped glyphs, SVG assets, fonts or runtime JavaScript. */
@layer syn.symbols {
  /* Every rule is scoped to a Syntyr root, including root-self use.
     Place on an inline SVG or a wrapper around an SVG. Keep icon artwork
     vendor-controlled: do not force stroke, fill, or stroke-width. */
  :where(.syn-root .syn-icon, .syn-root.syn-icon) {
    display: inline-block;
    inline-size: var(--syn-icon-size, 1.25em);
    block-size: var(--syn-icon-size, 1.25em);
    flex: none;
    vertical-align: -.15em;
  }
  :where(.syn-root .syn-icon > svg, .syn-root.syn-icon > svg) {
    display: block;
    inline-size: 100%;
    block-size: 100%;
  }

  /* Symbols belong in the DOM; CSS does not generate meaningful content. */
  :where(.syn-root .syn-symbol, .syn-root.syn-symbol) {
    display: inline-block;
    line-height: 1;
    vertical-align: -.075em;
  }
  :where(.syn-root .syn-symbol--accent, .syn-root.syn-symbol--accent) { color: var(--syn-accent, currentColor); }
  :where(.syn-root .syn-symbol--muted, .syn-root.syn-symbol--muted) { color: var(--syn-muted, currentColor); }

  /* Preserve ASCII / Unicode box geometry, with horizontal scroll instead
     of wrapping and breaking columns on a narrow screen. */
  :where(.syn-root .syn-ascii, .syn-root.syn-ascii) {
    display: block;
    max-inline-size: 100%;
    margin: 0;
    overflow-x: auto;
    white-space: pre;
    font-family: var(--syn-mono, ui-monospace, monospace);
    font-variant-ligatures: none;
    font-kerning: none;
    line-height: 1.4;
    tab-size: 4;
  }
  :where(.syn-root .syn-ascii--accent, .syn-root.syn-ascii--accent) { color: var(--syn-accent, currentColor); }
  :where(.syn-root .syn-ascii--muted, .syn-root.syn-ascii--muted) { color: var(--syn-muted, currentColor); }
}
